import { expect, test } from 'bun:test';
import { resolve } from 'node:path';
import type { UseCase } from '@agentic-ddd/core';
import type { ClassRef } from '@agentic-ddd/decorators';
import { OperatorRuntime, type UseCaseInstances } from '@agentic-ddd/runtime';
import { covers, FakeLlm, InMemoryEventBus } from '@agentic-ddd/testing';
import { CreateTask } from '../application/create-task';
import { CompleteTask } from '../application/complete-task';
import { TaskCreated, TaskCompleted } from '../domain/task.events';
import { InMemoryTaskRepository } from '../infrastructure/in-memory-task.repository';
import { TaskOperator } from '../operators/task.operator';

test(covers([
  'operator:task-operator',
  'criterion:0001/tools',
], 'cria e conclui a tarefa pelas duas tools e publica TaskCreated e TaskCompleted'), async () => {
  const repository = new InMemoryTaskRepository();
  const eventBus = new InMemoryEventBus();
  const llm = new FakeLlm([
    {
      stopReason: 'tool_calls',
      content: [{
        type: 'tool_call', id: 'create-1', name: 'create_task',
        input: { task_id: 't1', title: '  Revisar tarefa  ' },
      }],
    },
    async (request) => {
      const task = await repository.findById('t1');
      expect(task?.title).toBe('Revisar tarefa');
      expect(task?.status).toBe('pending');
      expect(eventBus.events).toHaveLength(1);
      expect(eventBus.events[0]).toBeInstanceOf(TaskCreated);
      expect(request.messages.at(-1)).toEqual({
        role: 'tool',
        results: [{
          toolCallId: 'create-1', isError: false,
          content: {
            output: { task_id: 't1', title: 'Revisar tarefa', status: 'pending' },
            events: [{ name: 'TaskCreated', payload: { taskId: 't1', title: 'Revisar tarefa' } }],
          },
        }],
      });
      return {
        stopReason: 'tool_calls',
        content: [{
          type: 'tool_call', id: 'complete-1', name: 'complete_task',
          input: { task_id: 't1' },
        }],
      };
    },
    (request) => {
      expect(request.messages.at(-1)).toEqual({
        role: 'tool',
        results: [{
          toolCallId: 'complete-1', isError: false,
          content: {
            output: { task_id: 't1', status: 'completed' },
            events: [{ name: 'TaskCompleted', payload: { taskId: 't1' } }],
          },
        }],
      });
      return {
        stopReason: 'end',
        content: [{ type: 'text', text: 'A tarefa t1 foi criada e concluída.' }],
      };
    },
  ]);
  const runtime = new OperatorRuntime({
    llm, eventBus, root: resolve(import.meta.dir, '../..'),
    modules: [{ name: 'tasks', path: 'app' }],
  });
  const instances: UseCaseInstances = new Map<ClassRef, UseCase<unknown, unknown>>([
    [CreateTask, new CreateTask(repository)],
    [CompleteTask, new CompleteTask(repository)],
  ]);
  await runtime.register(TaskOperator, instances);
  expect(await repository.findById('t1')).toBeNull();

  const result = await runtime.run('task-operator', {
    message: 'Crie a tarefa t1 com título Revisar tarefa e depois conclua t1.',
  });

  expect(result.status).toBe('completed');
  expect(result.operator).toBe('task-operator');
  expect(result.output).toBe('A tarefa t1 foi criada e concluída.');
  expect(llm.requests).toHaveLength(3);
  for (const request of llm.requests) {
    expect(request.tools.map((tool) => tool.name).sort()).toEqual(['complete_task', 'create_task']);
    expect(request.system).toContain('Identifique a tarefa pelo id e responda em português.');
  }
  const toolSteps = result.steps.flatMap((step) => step.tools);
  expect(toolSteps.map((step) => step.call.name)).toEqual(['create_task', 'complete_task']);
  expect(toolSteps.map((step) => step.result?.isError)).toEqual([false, false]);
  expect(toolSteps.map((step) => step.policy)).toEqual(['allow', 'allow']);

  const stored = await repository.findById('t1');
  expect(stored?.title).toBe('Revisar tarefa');
  expect(stored?.status).toBe('completed');
  expect(stored?.pullEvents()).toEqual([]);
  expect(eventBus.events).toHaveLength(2);
  expect(eventBus.events[0]).toBeInstanceOf(TaskCreated);
  expect(eventBus.events[0]?.payload).toEqual({ taskId: 't1', title: 'Revisar tarefa' });
  expect(eventBus.events[1]).toBeInstanceOf(TaskCompleted);
  expect(eventBus.events[1]?.payload).toEqual({ taskId: 't1' });
  expect(result.events).toEqual(eventBus.events);
  for (const [index, event] of eventBus.events.entries()) {
    expect(event.correlationId).toBe(result.runId);
    expect(event.causationId).toBe(result.steps[index]?.id);
    expect(toolSteps[index]?.events).toEqual([event]);
  }
});
